import sys
from functools import lru_cache

data = sys.stdin.read().split()
n = int(data[0])
arr = tuple(int(x) for x in data[1:1 + n])

@lru_cache(maxsize=None)
def solve(cur):
    if len(cur) == 1:
        return 0
    best = 0
    m = len(cur)
    for x in range(m):
        for y in range(m):
            if x == y:
                continue
            s = cur[x] ^ cur[y]
            rest = cur[:y] + cur[y + 1:]
            best = max(best, s + solve(rest))
    return best

print(solve(arr))

